import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"CommentList","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/comment-list.md","filePath":"workbench/comment-list.md"}'),d={name:"workbench/comment-list.md"};function n(s,e,i,h,c,m){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="commentlist" tabindex="-1">CommentList <a class="header-anchor" href="#commentlist" aria-label="Permalink to &quot;CommentList&quot;">​</a></h1><p>CommentList shows the conversations left on a document: each one&#39;s first message, its replies, and the actions to open and resolve it.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it in the comments panel of a drawing application. The application passes its threads in the order it wants them, filtered as it likes (without the resolved ones, for example). CommentList knows nothing of where a thread is on the stage: the application draws the pins, and moves to a thread and opens it when <code>onopen</code> is called. A reply is written with a <a href="./comment-composer">CommentComposer</a> that the application places where the thread opens.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>threads</code></td><td>required</td><td>The threads, <code>CommentThread[]</code></td></tr><tr><td><code>onopen</code></td><td></td><td>Shows the open action; called with the thread&#39;s id</td></tr><tr><td><code>onresolve</code></td><td></td><td>Shows resolve and reopen; called with <code>(id, resolved)</code></td></tr><tr><td><code>label</code></td><td>&quot;Comments&quot;</td><td>The name of the list</td></tr></tbody></table><p>A <code>CommentThread</code> is <code>{ id, author, when, body, replies?, resolved? }</code>, and each reply is <code>{ id, author, when, body }</code>. The <code>author</code> is <code>{ name, initial, color? }</code>: the name, the initials in the <a href="./../components/avatar">Avatar</a> and the person&#39;s color; <code>when</code> is the time as the application words it.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The threads are stacked with a <a href="./../components/divider">Divider</a> between them. A thread is a <a href="./../components/comment">Comment</a> for its first message, with a <a href="./../components/thread">Thread</a> of its replies under it, gap-sm apart; the bodies are text that wraps. The actions sit on the right of the first message&#39;s name: resolve (a check mark) or reopen (an arrow back) with <code>onresolve</code>, then open (an arrow out) with <code>onopen</code>. A resolved thread without <code>onresolve</code> shows a green Resolved <a href="./../components/badge">Badge</a> instead. Without threads, it shows a <a href="./../components/state">State</a> in a <a href="./../components/block">Block</a>. The messages are <code>comments</code>, <code>noComments</code>, <code>openThread</code>, <code>resolve</code>, <code>reopen</code> and <code>resolved</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/comment-list/" title="CommentList" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/comment-list/" target="_blank" rel="noopener">CommentList</a></figcaption></figure>',11)])])}const f=t(d,[["render",n]]);export{p as __pageData,f as default};
